// benchmarks/bench_math.cpp
#include <benchmark/benchmark.h>
#include <myproject/math.hpp>
#include <vector>
#include <random>
#include <algorithm>

static void BM_Mean(benchmark::State& state) {
    std::vector<double> data(state.range(0));
    std::mt19937 gen(42);
    std::uniform_real_distribution<> dis(0.0, 100.0);
    std::generate(data.begin(), data.end(), [&] { return dis(gen); });

    for (auto _ : state) {
        benchmark::DoNotOptimize(myproject::math::mean(data));
    }
    state.SetItemsProcessed(state.iterations() * data.size());
}
BENCHMARK(BM_Mean)->Arg(100)->Arg(1000)->Arg(10000)->Arg(100000);

static void BM_StdDev(benchmark::State& state) {
    std::vector<double> data(state.range(0));
    std::mt19937 gen(42);
    std::uniform_real_distribution<> dis(0.0, 100.0);
    std::generate(data.begin(), data.end(), [&] { return dis(gen); });

    for (auto _ : state) {
        benchmark::DoNotOptimize(myproject::math::stddev(data));
    }
    state.SetItemsProcessed(state.iterations() * data.size());
}
BENCHMARK(BM_StdDev)->Arg(100)->Arg(1000)->Arg(10000)->Arg(100000);

static void BM_ProcessorPipeline(benchmark::State& state) {
    myproject::ResourceManager rm;
    rm.register_processor(myproject::ProcessorFactory::create("mean"));
    rm.register_processor(myproject::ProcessorFactory::create("stddev"));

    std::vector<double> data(state.range(0));
    std::iota(data.begin(), data.end(), 1.0);

    for (auto _ : state) {
        auto result = rm.run_all(data);
        benchmark::DoNotOptimize(result);
    }
    state.SetItemsProcessed(state.iterations() * data.size());
}
BENCHMARK(BM_ProcessorPipeline)->Arg(100)->Arg(1000)->Arg(10000);

BENCHMARK_MAIN();
